export function getDocumentPreset(slug?: string | null) {
	return documentPresets.find((preset) => preset.slug === slug) ?? null;
}

type PresetDataFor<TType extends DocumentType> = TType extends "cover_page"
	? CoverPageData
	: IndexSheetData;

export function getDocumentPresetData<TType extends DocumentType>(
	slug: string | null | undefined,
	type: TType,
): PresetDataFor<TType> | null {
	const preset = getDocumentPreset(slug);
	if (!preset || preset.type !== type) return null;
	return structuredClone(preset.data) as PresetDataFor<TType>;
}
